<template>
 <main ref="root" class="policy-page">
  <nav aria-label="位置"><router-link to="/agents">Agent 管理</router-link> / <router-link to="/agents/execution-policies">执行策略</router-link> / 登记策略</nav>
  <header><div><h1>登记执行策略</h1><p>将真实角色、固定来源与运行时限制保存为不可变草稿，交由独立审批人审核。</p></div><el-tag type="warning">N00 · 非模型</el-tag></header>
  <session-panel />
  <el-alert type="info" :closable="false" title="当前登记表支持真实 N00 非模型策略" description="无模型、无 tokenizer、无检索配置，训练和外部请求均禁止。策略批准不会发布 Agent，也不能单独取得 TASK 执行资格。模型与索引配置不能手填版本号。" />
  <el-alert v-if="error" class="spaced" type="error" :closable="false" :title="error" role="alert" />
  <div class="actions"><el-button :disabled="busy" @click="restart">重新读取当前状态</el-button><router-link to="/agents/execution-policies">返回策略目录</router-link></div>
  <p v-if="loading" role="status">正在读取真实候选或核查固定声明…</p>
  <section v-if="availability?.features.policy_authoring === false" class="card"><h2>当前部署未启用执行策略服务</h2><p>请由管理员核查实际策略作者服务、授权与依赖配置。部署开关不会授予业务权限。</p></section>
  <execution-policy-recovery v-if="pending" :pending="pending" :lookup="lookup" :disabled="busy || availability?.features.policy_authoring !== true" @recover="recover" />
  <section v-if="saved" class="card result" role="status"><h2>原策略请求已核验</h2><p>原键、原记录、类型回执与固定声明一致。当前状态：{{ saved.status }}；不代表 Agent 已发布。</p><router-link :to="'/agents/execution-policies/'+saved.fixed.version_id">打开固定策略详情</router-link></section>
  <el-form v-if="availability?.features.policy_authoring && !pending" label-position="top" class="card spaced" :disabled="busy" @submit.prevent="submit">
   <h2>1. 归属与真实角色</h2>
   <el-form-item label="归属范围"><el-select v-model="project" filterable aria-label="归属范围"><el-option value="" label="当前企业"/><el-option v-for="p in projects" :key="p.project_id" :value="p.project_id" :label="p.name"/></el-select><el-button v-if="projectCursor" link @click="loadProjects(true)">读取更多项目</el-button></el-form-item>
   <el-form-item label="真实专业角色固定版本"><el-select v-model="roleId" filterable placeholder="从当前可访问的 ROLE 草稿选择" aria-label="专业角色"><el-option v-for="r in roles" :key="r.record_id" :value="r.record_id" :label="r.content.request.reason+' · '+r.resource_id"/></el-select><div class="actions"><el-button link @click="loadRoles(false)">读取角色候选</el-button><el-button v-if="roleCursor" link @click="loadRoles(true)">读取更多角色</el-button></div><p>ROLE 草稿是政策依赖，独立策略审批仍需重新核查真实来源与 AGENT_PUBLICATION 用途。不会将角色草稿标记为已发布。</p><p v-if="rolesLoaded && !roles.length">当前页没有可用 ROLE 候选。{{ roleCursor ? '可继续读取下一页。' : '请先登记当前范围的真实专业角色。' }}</p><router-link to="/agents/capabilities">打开正式能力目录</router-link></el-form-item>
   <section v-if="selectedRole" class="inset"><p>固定角色版本：{{ selectedRole.resource_id }}</p><small>SHA-256：{{ selectedRole.content_sha256 }}</small><h3>选择角色已声明的节点动作</h3><p>声明只限制后续运行。实际任务、来源、角色范围和当前授权仍由服务端逐项匹配。</p><el-checkbox-group v-model="actionKeys"><el-checkbox v-for="a in actionCandidates" :key="canonical(a)" :value="canonical(a)">{{ a.action }} · {{ a.target_selector }} · {{ a.purpose }}</el-checkbox></el-checkbox-group><p v-if="!actionCandidates.length">该角色没有适用于此 N00 表单的任务、项目或来源读取动作，不能创建空权限节点。</p></section>
   <h2>2. 固定来源与用途</h2>
   <el-form-item label="可读且已审批的来源候选"><el-select v-model="sourceId" filterable placeholder="选择实际来源版本" aria-label="来源候选"><el-option v-for="s in sources" :key="s.source_version" :value="s.source_version" :label="s.title+' · '+s.source_version"/></el-select><div class="actions"><el-button link @click="loadSources(false)">读取来源候选</el-button><el-button v-if="sourceCursor" link @click="loadSources(true)">读取更多来源</el-button><el-button :disabled="!sourceId || busy" @click="addSource">核查并加入来源</el-button></div><p>加入时读取固定版本、当前权利与 DOCUMENT_BODY 用途；提交前重新核查全部选择。完整权利闭包、部署环境和区域由服务端再次验证。</p></el-form-item>
   <ul class="selection"><li v-for="(s,index) in selectedSources" :key="s.source_version"><div><strong>{{ s.title }}</strong><p>{{ s.classification }} · {{ s.rights_purpose }} · {{ s.rights_status }}</p><small>版本 {{ s.source_version }} · 权利修订 {{ s.rights_revision }}</small><small>SHA-256：{{ s.original_sha256 }}</small></div><el-button type="danger" link :disabled="busy" @click="selectedSources.splice(index,1)">移除来源</el-button></li></ul>
   <p v-if="!selectedSources.length">尚未选择来源；不包含来源读取动作的 N00 策略允许空来源集合。</p>
   <el-form-item label="允许的数据分类"><el-checkbox-group v-model="classifications"><el-checkbox v-for="c in classificationOptions" :key="c" :value="c">{{ c }}</el-checkbox></el-checkbox-group></el-form-item>
   <el-form-item label="项目证据用途"><el-input v-model="profilePurpose" maxlength="64" placeholder="填写真实获准的用途代码"/><small>用途目录尚未公开，输入用途不等于获得许可。</small></el-form-item>
   <h2>3. 实际运行配置</h2><p>当前没有 Worker 身份与部署配置的可选目录。请填写管理员提供的真实配置，服务端会验证实际环境及运行时身份；本表单不会注册服务或创建凭据。</p>
   <div class="form-grid"><el-form-item label="Worker 服务身份 URI"><el-input v-model="workerUri" placeholder="真实服务身份 URI，不含凭据" autocomplete="off" maxlength="512"/></el-form-item><el-form-item label="Worker audience"><el-input v-model="audience" maxlength="256" autocomplete="off"/></el-form-item><el-form-item label="部署环境"><el-input v-model="environment" maxlength="128"/></el-form-item><el-form-item label="区域"><el-input v-model="region" maxlength="128"/></el-form-item><el-form-item label="语言"><el-input v-model="locale" maxlength="64"/></el-form-item><el-form-item label="时区"><el-input v-model="timezone" maxlength="128"/></el-form-item><el-form-item label="生效时间（UTC）"><input v-model="validFrom" type="datetime-local" step="1" :disabled="busy" aria-label="生效时间（UTC）" /></el-form-item><el-form-item label="结束时间（UTC，可选）"><input v-model="validUntil" type="datetime-local" step="1" :disabled="busy" aria-label="结束时间（UTC）" /></el-form-item></div>
   <el-form-item label="登记原因"><el-input v-model="reason" type="textarea" :rows="3" maxlength="2000" show-word-limit /></el-form-item>
   <el-checkbox v-model="attested">已核查完整范围、真实配置与用途，确认保存不可变草稿后由独立审批人审核</el-checkbox><p v-if="!mayAuthor">当前归属范围没有 agent.configure 权限。</p>
   <div class="actions"><el-button type="primary" native-type="submit" :disabled="busy || !mayAuthor || !attested || !selectedRole || !actionKeys.length">保存执行策略草稿</el-button><el-button :disabled="busy" @click="clearForm">清除未提交表单</el-button></div>
  </el-form>
  <el-dialog v-model="leaveDialog" title="离开未提交的策略？" width="min(94vw,480px)" :close-on-click-modal="false"><p>未提交表单将清除。已保存的原请求会保留，离开页面不会取消服务器操作。</p><template #footer><el-button @click="leaveDialog=false">继续填写</el-button><el-button type="danger" @click="confirmLeave">清除表单并离开</el-button></template></el-dialog>
 </main>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { onBeforeRouteLeave, useRouter } from 'vue-router'
import SessionPanel from './session-panel.vue'
import ExecutionPolicyRecovery from './execution-policy-recovery.vue'
import { usePolicyPage } from '@/api/medical/use-execution-policy-page'
import { canonical, detached, policyAllowed, policyInputIssue, readPendingPolicy } from '@/api/medical/execution-policy-domain'
import type { PendingPolicy, PolicyAuthor, PolicyAvailability, PolicyView } from '@/api/medical/execution-policy-domain'
import { authorPolicy, readPolicyAvailability, recoverPolicy } from '@/api/medical/execution-policies'
import { policyProjectCandidates, policyRoleCandidates, policyActionCandidates, policySourceCandidates, inspectPolicySource, recheckPolicyCandidates } from '@/api/medical/execution-policy-candidates'
import type { FormalCapabilityRecord } from '@/api/medical/formal-capability-domain'
import type { SourceCatalogueItem, SourceGovernanceView } from '@/api/medical/source-governance'
import type { Project } from '@/api/medical/protocol'
import type { OperationLookup } from '@/api/medical/operations'
const router=useRouter(),root=ref<HTMLElement|null>(null),availability=ref<PolicyAvailability|null>(null),pending=ref<PendingPolicy|null>(null),lookup=ref<OperationLookup|null>(null),saved=ref<PolicyView|null>(null)
const projects=ref<Project[]>([]),projectCursor=ref<string|null>(null),roles=ref<FormalCapabilityRecord[]>([]),roleCursor=ref<string|null>(null),rolesLoaded=ref(false),sources=ref<SourceCatalogueItem[]>([]),sourceCursor=ref<string|null>(null)
const project=ref(''),roleId=ref(''),actionKeys=ref<string[]>([]),sourceId=ref(''),selectedSources=ref<SourceGovernanceView[]>([]),classifications=ref<string[]>(['PUBLIC','INTERNAL']),classificationOptions=['PUBLIC','INTERNAL','RESTRICTED','PERSONAL_HEALTH']
const profilePurpose=ref(''),workerUri=ref(''),audience=ref(''),environment=ref(''),region=ref(''),locale=ref('zh-CN'),timezone=ref('UTC'),validFrom=ref(''),validUntil=ref(''),reason=ref(''),attested=ref(false),leaveDialog=ref(false)
let leaveApproved=false,leavePath=''
const page=usePolicyPage(reset,bootstrap),{user,loading,error,busy,reader}=page
const selectedRole=computed(()=>roles.value.find(r=>r.record_id===roleId.value)??null),actionCandidates=computed(()=>policyActionCandidates(selectedRole.value,project.value||null)),mayAuthor=computed(()=>policyAllowed(user.medicalSession,project.value||null,'agent.configure'))
function clearForm(){project.value='';roleId.value='';actionKeys.value=[];sourceId.value='';selectedSources.value=[];classifications.value=['PUBLIC','INTERNAL'];profilePurpose.value='';workerUri.value='';audience.value='';environment.value='';region.value='';locale.value='zh-CN';timezone.value='UTC';validFrom.value='';validUntil.value='';reason.value='';attested.value=false}
function reset(){root.value?.querySelectorAll<HTMLInputElement|HTMLTextAreaElement>('input,textarea').forEach(el=>{el.value='';if(el instanceof HTMLInputElement)el.checked=false});clearForm();availability.value=null;pending.value=null;lookup.value=null;saved.value=null;projects.value=[];projectCursor.value=null;roles.value=[];roleCursor.value=null;rolesLoaded.value=false;sources.value=[];sourceCursor.value=null;leaveDialog.value=false}
async function bootstrap(){await page.run(async(signal,current)=>{pending.value=readPendingPolicy(reader());const a=await readPolicyAvailability(reader,signal);if(!current())return;availability.value=a;if(a.features.policy_authoring&&!pending.value){const p=await policyProjectCandidates(reader,null,signal);if(current()){projects.value=p.projects;projectCursor.value=p.next_after}}})}
function restart(){if(busy.value)return;page.clear();void bootstrap()}
async function loadProjects(next:boolean){if(busy.value)return;const cursor=next?projectCursor.value:null;if(next&&!cursor)return;await page.run(async(signal,current)=>{const p=await policyProjectCandidates(reader,cursor,signal);if(current()){const items=next?[...projects.value,...p.projects]:p.projects;if(new Set(items.map(x=>x.project_id)).size!==items.length)throw new Error('项目目录发生变化，请重新读取');projects.value=items;projectCursor.value=p.next_after}})}
async function loadRoles(next:boolean){if(busy.value)return;const cursor=next?roleCursor.value:null,scope=project.value;if(next&&!cursor)return;if(!next){roles.value=[];roleId.value='';roleCursor.value=null;rolesLoaded.value=false}await page.run(async(signal,current)=>{const p=await policyRoleCandidates(reader,scope||null,cursor,signal);if(current()&&project.value===scope){const items=next?[...roles.value,...p.items]:p.items;if(new Set(items.map(x=>x.record_id)).size!==items.length)throw new Error('角色目录发生变化，请重新读取');roles.value=items;roleCursor.value=p.next_cursor;rolesLoaded.value=true}})}
async function loadSources(next:boolean){if(busy.value)return;const cursor=next?sourceCursor.value:null,scope=project.value;if(next&&!cursor)return;if(!next){sources.value=[];sourceId.value='';sourceCursor.value=null}await page.run(async(signal,current)=>{const p=await policySourceCandidates(reader,scope||null,cursor,signal);if(current()&&scope===project.value){const items=next?[...sources.value,...p.items]:p.items;if(new Set(items.map(x=>x.source_version)).size!==items.length)throw new Error('来源目录发生变化，请重新读取');sources.value=items;sourceCursor.value=p.next_after}})}
async function addSource(){if(busy.value)return;const item=sources.value.find(x=>x.source_version===sourceId.value);if(!item||selectedSources.value.some(x=>x.source_version===item.source_version)||selectedSources.value.length>=1000)return;const scope=project.value;await page.run(async(signal,current)=>{const source=await inspectPolicySource(reader,item,scope||null,signal);if(current()&&scope===project.value){selectedSources.value.push(source);sourceId.value=''}})}
function makeBody():PolicyAuthor {const role=selectedRole.value;if(!role)throw new Error('请选择真实专业角色');if(project.value&&!projects.value.some(x=>x.project_id===project.value))throw new Error('请选择真实可访问项目');if(!validFrom.value)throw new Error('请填写策略生效时间');const actions=actionKeys.value.map(key=>{const a=actionCandidates.value.find(x=>canonical(x)===key);if(!a)throw new Error('动作候选已变化，请重新选择');return detached(a)})
 return {schema_version:'1.0.0',reason:reason.value,definition:{schema_version:'1.0.0',project_id:project.value||null,business_purpose:'DOCUMENT_BODY',profile_evidence_purpose:profilePurpose.value,allowed_classifications:[...classifications.value],source_selection:{mode:'FIXED_SOURCE_VERSIONS',sources:selectedSources.value.map(s=>({version_id:s.source_version,content_sha256:s.original_sha256}))},retrieval_profiles:[],network_policy:{https_origins:[],external_requests_allowed:false},worker:{service_uri:workerUri.value,audience:audience.value},bindings:[{node_kind:'N00',role_version:{version_id:role.resource_id,content_sha256:role.content_sha256},model_version:null,tokenizer_version:null,tokenizer_artifact:null,generation_parameters:{},actions}],locale:locale.value,timezone:timezone.value,environment:environment.value,region:region.value,training_allowed:false,valid_from:new Date(validFrom.value+'Z').toISOString(),valid_until:validUntil.value?new Date(validUntil.value+'Z').toISOString():null}}
}
async function submit(){if(busy.value||pending.value||!attested.value||!mayAuthor.value||!availability.value?.features.policy_authoring)return;let body:PolicyAuthor;try{body=makeBody();const issue=policyInputIssue('EXECUTION_POLICY_AUTHOR',body);if(issue)throw new Error(issue)}catch(failure){error.value=failure instanceof Error?failure.message:'请核查完整声明';return}const role=selectedRole.value!,chosen=detached(selectedSources.value)
 await page.run(async(signal,current)=>{try{await recheckPolicyCandidates(reader,body,role,chosen,signal);if(!current())return;const p=await authorPolicy(reader,body,signal,value=>{if(current())pending.value=value});if(!current())return;attested.value=false;const result=await recoverPolicy(reader,p,signal);if(current()){lookup.value=result.lookup;if(result.view){pending.value=null;clearForm();saved.value=result.view}}}finally{if(current())pending.value=readPendingPolicy(reader())}},true)
}
async function recover(){const p=pending.value;if(!p)return;await page.run(async(signal,current)=>{const result=await recoverPolicy(reader,p,signal);if(current()){lookup.value=result.lookup;if(result.view){pending.value=null;clearForm();saved.value=result.view}}})}
function dirty(){return !pending.value&&(!!project.value||!!roleId.value||!!sourceId.value||selectedSources.value.length>0||!!profilePurpose.value||!!workerUri.value||!!audience.value||!!environment.value||!!region.value||!!validFrom.value||!!validUntil.value||!!reason.value||attested.value||locale.value!=='zh-CN'||timezone.value!=='UTC'||canonical(classifications.value)!==canonical(['PUBLIC','INTERNAL']))}
function unload(e:BeforeUnloadEvent){if(dirty()||page.writing()){e.preventDefault();e.returnValue=''}}
async function confirmLeave(){clearForm();leaveDialog.value=false;leaveApproved=true;try{await router.push(leavePath)}finally{leaveApproved=false;leavePath=''}}
onBeforeRouteLeave(to=>{if(user.medicalWriting)return false;if(leaveApproved||!dirty())return true;leavePath=to.fullPath;leaveDialog.value=true;return false})
watch([project,roleId,actionKeys,selectedSources,classifications,profilePurpose,workerUri,audience,environment,region,locale,timezone,validFrom,validUntil,reason],()=>{attested.value=false;saved.value=null},{deep:true,flush:'sync'})
watch(project,()=>{roles.value=[];roleCursor.value=null;rolesLoaded.value=false;roleId.value='';sources.value=[];sourceCursor.value=null;sourceId.value='';selectedSources.value=[]},{flush:'sync'})
watch(roleId,()=>{actionKeys.value=[]},{flush:'sync'})
window.addEventListener('beforeunload',unload);onBeforeUnmount(()=>window.removeEventListener('beforeunload',unload));page.start()
</script>
<style scoped src="./execution-policy.css"></style>
